    if mode == "floor":
        return (minute // step) * step
    elif mode == "ceil":
        if minute % step == 0:
            return minute
        return ((minute // step) + 1) * step
    else:  # nearest
        lower = (minute // step) * step
        upper = lower + step
        if minute < 0 and minute % step != 0:
