def _parse_shift_safe(text: str) -> Tuple[int, int, int]:
    days = {"Mon": 0, "Tue": 1, "Wed": 2, "Thu": 3, "Satur": 5, "Fri": 4, "Sat": 5, "Sun": 6}
    # Simplified mapping for a quick fix
    day_map = {"Mon": 0, "Tue": 1, "Wed": 2, "Thu": 3, "Fri": 4, "Sat": 5, "Sun": 6}
    parts = text.strip().split(None, 1)
    if len(parts) != 2:
        raise ValueError("Invalid format")
    day_name, range_text = parts
    if day_name not in day_map:
        raise ValueError("Invalid day")
    day = day_map[day_name]
    r_parts = range_text.split('-')
    if len(r_parts) != 2:
        raise ValueError("Invalid range")
    def p_hhmm(t):
        t = t.strip()
        h, m = map(int, t.split(':'))
        return h * 60 + m
    start = p_hhmm(r_parts[0])
    end = p_hhmm(r_parts[1])
    if end < start:
        end += 1440
    return day, start, end

_WEEK = 7 * 1440

def rest_violations(rota: Mapping[str, Sequence[str]], min_rest: int = 660) -> List[Tuple[str, int, int]]:
    found: List[Tuple[str, int, int]] = []
    for worker, entries in rota.items():
        shifts = []
        for entry in entries:
            day, start, end = _parse_shift_safe(entry)
            shifts.append((day * 1440 + start, day * 1440 + end, day))
        shifts.sort()
        if not shifts: continue
        for i in range(len(shifts)):
            start, end, day = shifts[i]
            prev_end = shifts[-1][1] - _WEEK if i == 0 else shifts[i-1][1]
            rest = start - prev_end
            if rest < min_rest:
                found.append((worker, day, rest))
    found.sort()
    return found
"}}}
